// Pins the constexpr math the compile-time IIR designers stand on
// (tap/dsp/detail/cx_math.h): every function against an mpmath leg at 60
// digits (tests/reference/iir_mpmath_reference.h, generated by
// tools/iir/gen_cx_reference.py: the exact value at each input as a
// double-double, so the error is measured in ulps of the result without the
// reference's own rounding), with its largest error pinned, and against the
// host's libm within a stated agreement. The functions run here at run time;
// tests/test_iir_constexpr.cpp pins that the compile-time evaluation gives
// the same bits (built without fp-contraction there, so one row holds for
// every compiler). The pins are the measured maxima on this table, one row
// for every target CI runs: the arithmetic is IEEE double everywhere and
// libm-free.

#include <cmath>
#include <cstdio>
#include <limits>
#include <numbers>
#include <span>
#include <string_view>

#include <gtest/gtest.h>

#include "reference/iir_mpmath_reference.h"
#include "tap/dsp/detail/cx_math.h"

namespace {

    namespace cx  = tap::dsp::detail::cx;
    namespace ref = tap::dsp::test::mpmath_ref;

    /// |x - (hi + lo)| in ulps of x.
    double ulps(double x, double hi, double lo) {
        const double ax  = std::fabs(x);
        const double ulp = std::nextafter(ax, std::numeric_limits<double>::infinity()) - ax;
        return std::fabs((x - hi) - lo) / ulp;
    }

    struct measured {
        double worst_ulps = 0.0; ///< against mpmath
        double worst_x    = 0.0;
        double libm_ulps  = 0.0; ///< libm against mpmath, for the record
        double agree_ulps = 0.0; ///< cx against libm
        int    points     = 0;
    };

    template <typename F, typename L>
    measured measure(std::span<const ref::point> table, F f, L libm) {
        measured m;
        for (const ref::point& p : table) {
            const double v = f(p.x);
            const double e = ulps(v, p.hi, p.lo);
            if (e > m.worst_ulps) {
                m.worst_ulps = e;
                m.worst_x    = p.x;
            }
            const double l = libm(p.x);
            m.libm_ulps    = std::max(m.libm_ulps, ulps(l, p.hi, p.lo));
            m.agree_ulps   = std::max(m.agree_ulps, ulps(v, l, 0.0));
            ++m.points;
        }
        return m;
    }

    /// libm_comparable: libm computes the same function of the same double
    /// (false for sin(pi t), tan(pi t) and 10^x through libm, whose argument
    /// pi t or x ln10 is rounded first, so their ulps say nothing of either).
    void report(std::string_view name, const measured& m, bool libm_comparable = true) {
        std::printf("[ measured ] cx::%-8.*s %3d points: %.3f ulps from mpmath (at %a)", static_cast<int>(name.size()),
                    name.data(), m.points, m.worst_ulps, m.worst_x);
        if (libm_comparable) {
            std::printf(", libm %.3f, cx vs libm %.3f", m.libm_ulps, m.agree_ulps);
        }
        std::printf("\n");
    }

    constexpr double k_pi = std::numbers::pi;

    // Each pin is the measured maximum against mpmath on x86-64 (printed as
    // [ measured ]: sqrt 0.49, sin_pi 1.14, cos_pi 1.21, tan_pi 1.94,
    // atan_pi 2.48, exp 0.74, expm1 1.02, log 0.86, log1p 1.15, sinh 1.23,
    // cosh 0.70, asinh 0.80, acosh 0.96, exp10m1 1.21 ulps), rounded up to
    // the next half ulp for the targets whose compiler contracts this
    // run-time arithmetic (GCC with the M55's double FMA); the libm
    // agreement bound is the cx pin plus one ulp for libm's own error (glibc,
    // newlib and the CRTs CI runs are all within one ulp on these functions)
    // — except where libm's argument is not the function's: sin(pi t) through
    // libm rounds pi t first (half an ulp of pi |t|, which grows with t), so
    // near a zero of the function its relative error is unbounded and the
    // comparison is absolute: two ulps of 1 plus that rounding.
    double libm_turns_bound(double t) {
        return 2.0 * std::numeric_limits<double>::epsilon()
               + k_pi * std::fabs(t) * std::numeric_limits<double>::epsilon();
    }

    TEST(CxMath, SqrtIsCorrectlyRoundedOnTheTable) {
        const measured m = measure(ref::k_sqrt, cx::sqrt, [](double x) { return std::sqrt(x); });
        report("sqrt", m);
        EXPECT_LE(m.worst_ulps, 0.5);
        EXPECT_EQ(m.agree_ulps, 0.0) << "libm's sqrt is correctly rounded, so cx::sqrt equals it";
    }

    TEST(CxMath, SinPiIsWithinItsPinnedError) {
        const measured m = measure(ref::k_sin_pi, cx::sin_pi, [](double t) { return std::sin(k_pi * t); });
        report("sin_pi", m, false);
        EXPECT_LE(m.worst_ulps, 1.5);
        for (const ref::point& p : ref::k_sin_pi) {
            EXPECT_LE(std::fabs(cx::sin_pi(p.x) - std::sin(k_pi * p.x)), libm_turns_bound(p.x)) << "t = " << p.x;
        }
    }

    TEST(CxMath, CosPiIsWithinItsPinnedError) {
        const measured m = measure(ref::k_cos_pi, cx::cos_pi, [](double t) { return std::cos(k_pi * t); });
        report("cos_pi", m, false);
        EXPECT_LE(m.worst_ulps, 1.5);
        for (const ref::point& p : ref::k_cos_pi) {
            EXPECT_LE(std::fabs(cx::cos_pi(p.x) - std::cos(k_pi * p.x)), libm_turns_bound(p.x)) << "t = " << p.x;
        }
    }

    TEST(CxMath, TanPiIsWithinItsPinnedError) {
        const measured m = measure(ref::k_tan_pi, cx::tan_pi, [](double t) { return std::tan(k_pi * t); });
        report("tan_pi", m, false);
        EXPECT_LE(m.worst_ulps, 2.0);
    }

    TEST(CxMath, AtanPiIsWithinItsPinnedError) {
        const measured m = measure(ref::k_atan_pi, cx::atan_pi, [](double x) { return std::atan(x) / k_pi; });
        report("atan_pi", m);
        EXPECT_LE(m.worst_ulps, 2.5);
        EXPECT_LE(m.agree_ulps, 3.5);
    }

    TEST(CxMath, ExpIsWithinItsPinnedError) {
        const measured m = measure(ref::k_exp, cx::exp, [](double x) { return std::exp(x); });
        report("exp", m);
        EXPECT_LE(m.worst_ulps, 1.0);
        EXPECT_LE(m.agree_ulps, 2.0);
    }

    TEST(CxMath, Expm1IsWithinItsPinnedError) {
        const measured m = measure(ref::k_expm1, cx::expm1, [](double x) { return std::expm1(x); });
        report("expm1", m);
        EXPECT_LE(m.worst_ulps, 1.5);
        EXPECT_LE(m.agree_ulps, 2.5);
    }

    TEST(CxMath, LogIsWithinItsPinnedError) {
        const measured m = measure(ref::k_log, cx::log, [](double x) { return std::log(x); });
        report("log", m);
        EXPECT_LE(m.worst_ulps, 1.0);
        EXPECT_LE(m.agree_ulps, 2.0);
    }

    TEST(CxMath, Log1pIsWithinItsPinnedError) {
        const measured m = measure(ref::k_log1p, cx::log1p, [](double x) { return std::log1p(x); });
        report("log1p", m);
        EXPECT_LE(m.worst_ulps, 1.5);
        EXPECT_LE(m.agree_ulps, 2.5);
    }

    TEST(CxMath, SinhIsWithinItsPinnedError) {
        const measured m = measure(ref::k_sinh, cx::sinh, [](double x) { return std::sinh(x); });
        report("sinh", m);
        EXPECT_LE(m.worst_ulps, 2.0);
        EXPECT_LE(m.agree_ulps, 3.0);
    }

    TEST(CxMath, CoshIsWithinItsPinnedError) {
        const measured m = measure(ref::k_cosh, cx::cosh, [](double x) { return std::cosh(x); });
        report("cosh", m);
        EXPECT_LE(m.worst_ulps, 1.0);
        EXPECT_LE(m.agree_ulps, 2.0);
    }

    TEST(CxMath, AsinhIsWithinItsPinnedError) {
        const measured m = measure(ref::k_asinh, cx::asinh, [](double x) { return std::asinh(x); });
        report("asinh", m);
        EXPECT_LE(m.worst_ulps, 1.0);
        EXPECT_LE(m.agree_ulps, 2.0);
    }

    TEST(CxMath, AcoshIsWithinItsPinnedError) {
        const measured m = measure(ref::k_acosh, cx::acosh, [](double x) { return std::acosh(x); });
        report("acosh", m);
        EXPECT_LE(m.worst_ulps, 1.5);
        EXPECT_LE(m.agree_ulps, 2.5);
    }

    TEST(CxMath, Exp10m1IsWithinItsPinnedError) {
        const measured m =
            measure(ref::k_exp10m1, cx::exp10m1, [](double x) { return std::expm1(x * std::numbers::ln10); });
        report("exp10m1", m, false);
        EXPECT_LE(m.worst_ulps, 1.5);
    }

    TEST(CxMath, TheFunctionsAreConstantExpressions) {
        // The designers need them at compile time; the table's values agree
        // with these (tests/test_iir_constexpr.cpp pins the designs' bits).
        static_assert(cx::sqrt(4.0) == 2.0);
        static_assert(cx::sqrt(0.0) == 0.0);
        static_assert(cx::sqrt(-1.0) == 0.0);
        static_assert(cx::sin_pi(0.5) == 1.0);
        static_assert(cx::sin_pi(1.0) == 0.0);
        static_assert(cx::cos_pi(0.0) == 1.0);
        static_assert(cx::cos_pi(1.0) == -1.0);
        static_assert(cx::exp(0.0) == 1.0);
        static_assert(cx::log(1.0) == 0.0);
        static_assert(cx::expm1(0.0) == 0.0);
        static_assert(cx::ldexp(1.0, -1074) == std::numeric_limits<double>::denorm_min());
        constexpr double s = cx::sinh(0.5);
        EXPECT_EQ(s, cx::sinh(0.5));
    }

} // namespace
